/* i18n.js — Gram Edge Farm mini-app languages (7):
 *   English (default), Arabic, Russian, Spanish, Hindi, Chinese, Bengali.
 *
 * Scope: the MINI APP UI only (index.html). Bot messages, admin panel and
 * server logs stay English on purpose.
 *
 * HOW IT WORKS (so index.html did not have to be rewritten):
 *   • The app keeps writing plain English text into the DOM, exactly as before.
 *   • This file watches the DOM (MutationObserver) and swaps every English
 *     text node / placeholder / title / aria-label for its translation from the
 *     DICTIONARY below. English is the "source" language: the original text is
 *     remembered per node, so switching language (or back to English) always
 *     re-translates from the English source.
 *   • Dictionary KEYS are the exact English strings. A key may contain numbered
 *     placeholders {0} {1} … for dynamic parts, e.g.
 *         'Day {0} of {1}'  →  'Día {0} de {1}'
 *     Numbers, names etc. are captured and copied through.
 *   • To translate a NEW piece of UI text: add ONE line to DICTIONARY with the
 *     English text followed by ru, ar, es, hi, zh, bn. Text with no entry
 *     simply stays English.
 *
 *   window.i18n.lang()          current language code ('en' | 'ru' | 'ar' | 'es' | 'hi' | 'zh' | 'bn')
 *   window.i18n.setLang(code)   switch + persist (localStorage 'gef_lang')
 *   window.i18n.t(key, ...args) translate a string from JS code (for native
 *                               popups that don't go through the DOM)
 *   window.i18n.tr(text)        translate one string, no placeholders
 *   window.i18n.onChange(cb)    call cb(code) after every language switch
 *   window.i18n.LANGS           { en:{name,short,dir,flag}, ru:{…}, … }
 *   window.i18n.missing()       debug: list visible English strings with no translation
 */
